export const CATEGORIES = [
  { id: "all", label: "All", short: "ALL" },
  ...TPT_SECTIONS.map((s) => ({ id: s.id, label: s.label, short: s.short })),
];

export const MATERIALS = TPT_MATERIALS;

const BY_ID = new Map(TPT_MATERIALS.map((m) => [m.id, m]));
export function findTptMaterial(id) {
  return BY_ID.get(id) || { id: id | 0, abbr: "?", name: "Unknown", color: "#ff00ff", section: "special", desc: "" };
}

export const findMaterial = findTptMaterial;

export function searchTptMaterials(query, category) {
  const q = (query || "").trim().toLowerCase();
  return TPT_MATERIALS.filter((m) => {
    if (category && category !== "all" && m.section !== category) return false;
    if (!q) return true;
    return (
      m.name.toLowerCase().includes(q) ||
      m.abbr.toLowerCase().includes(q) ||
      (m.desc || "").toLowerCase().includes(q)
    );
  });
}

export const searchMaterials = searchTptMaterials;

export function isWallMaterial(id) { return (id | 0) >= WALL_ID_BASE && (id | 0) < WALL_ID_BASE + 64; }
export function wallIdOf(id) { return (id | 0) - WALL_ID_BASE; }
export function elementIdOf(id) { return id | 0; }

// Convenience ids for the default brush.
export const DEFAULT_MATERIAL_ID = 44;
export const DEFAULT_CATEGORY = "powders";
